"use client";

import { useState, useRef } from "react";
import { Bookmark, Play, Music, Volume2 } from "lucide-react";

const HITARU_SAD = "data:image/png;base64,";
const HITARU_CALM = "data:image/png;base64,";
const HITARU_HAPPY = "data:image/png;base64,";

const TAG_GRADIENTS = {
  花: "linear-gradient(160deg, #F3C9D6 0%, #E8A5BE 45%, #C9748F 100%)",
  景色: "linear-gradient(160deg, #BFD9C8 0%, #8FB89F 45%, #5B7D63 100%)",
  動物: "linear-gradient(160deg, #E4D2AE 0%, #CBA96F 45%, #8C6A3F 100%)",
  空: "linear-gradient(160deg, #CFE0F0 0%, #9DBEDC 45%, #6488AA 100%)",
};

const ITEMS = [
  { id: 1, kind: "image", tag: "花" },
  { id: 2, kind: "image", tag: "景色" },
  { id: 3, kind: "video", tag: "動物" },
  { id: 4, kind: "image", tag: "景色" },
  { id: 5, kind: "image", tag: "花" },
  { id: 6, kind: "video", tag: "動物" },
  { id: 7, kind: "image", tag: "空" },
  { id: 8, kind: "image", tag: "花" },
  { id: 9, kind: "video", tag: "動物" },
  { id: 10, kind: "image", tag: "景色" },
];

const PALETTE = {
  ink: "#2E332A",
  paper: "#F5F3EC",
  moss: "#5B6F52",
  dusk: "#8577A0",
  blush: "#C98B86",
  mist: "#E4E1D6",
};

const COMPANION_STAGES = [
  { label: "そばにいる", threshold: 0 },
  { label: "ほのかに色づく", threshold: 3 },
  { label: "やわらかく光る", threshold: 6 },
  { label: "小さく揺れる", threshold: 9 },
  { label: "微笑む", threshold: 13 },
  { label: "くるくる回る", threshold: 18 },
];

export default function IyashiPrototype() {
  const [view, setView] = useState("feed");
  const [index, setIndex] = useState(0);
  const [hidden, setHidden] = useState(new Set());
  const [saved, setSaved] = useState(new Set());
  const [videoAudioOn, setVideoAudioOn] = useState(new Set());
  const [viewerIndex, setViewerIndex] = useState(null);
  const [sessionTicks, setSessionTicks] = useState(0);
  const [growthBest, setGrowthBest] = useState(0);
  const [drag, setDrag] = useState({ x: 0, y: 0, active: false });
  const [flash, setFlash] = useState(null);
  const start = useRef({ x: 0, y: 0 });
  const axis = useRef(null);

  const visible = ITEMS.filter((it) => !hidden.has(it.id));

  const registerTick = () => {
    setSessionTicks((t) => {
      const next = t + 1;
      setGrowthBest((b) => Math.max(b, next));
      return next;
    });
  };

  const stageIndexFor = (ticks) => {
    let idx = 0;
    for (let i = 0; i < COMPANION_STAGES.length; i++) {
      if (ticks >= COMPANION_STAGES[i].threshold) idx = i;
    }
    return idx;
  };

  const sessionStage = stageIndexFor(sessionTicks);

  const safeIndex = Math.min(index, Math.max(visible.length - 1, 0));
  const current = visible[safeIndex];
  const next = visible[safeIndex + 1];

  const showFlash = (label) => {
    setFlash(label);
    setTimeout(() => setFlash(null), 600);
  };

  const onDown = (e) => {
    const p = e.touches ? e.touches[0] : e;
    start.current = { x: p.clientX, y: p.clientY };
    axis.current = null;
    setDrag({ x: 0, y: 0, active: true });
  };

  const onMove = (e) => {
    if (!drag.active) return;
    const p = e.touches ? e.touches[0] : e;
    const dx = p.clientX - start.current.x;
    const dy = p.clientY - start.current.y;
    if (!axis.current && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
      axis.current = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
    }
    setDrag({ x: axis.current === "x" ? dx : 0, y: axis.current === "y" ? dy : 0, active: true });
  };

  const onUp = () => {
    const { x, y } = drag;
    const THRESH_X = 90;
    const THRESH_Y = 70;

    if (axis.current === "x" && Math.abs(x) > THRESH_X && current) {
      if (x > 0) {
        setSaved((s) => new Set(s).add(current.id));
        showFlash("保存しました");
        setIndex((i) => Math.min(i + 1, visible.length - 1));
      } else {
        setHidden((h) => new Set(h).add(current.id));
        showFlash("表示しません");
      }
      registerTick();
      setDrag({ x: 0, y: 0, active: false });
      axis.current = null;
      return;
    }

    if (axis.current === "y" && Math.abs(y) > THRESH_Y) {
      if (y < 0 && safeIndex < visible.length - 1) {
        setIndex((i) => i + 1);
        registerTick();
      }
      if (y > 0 && safeIndex > 0) {
        setIndex((i) => i - 1);
        registerTick();
      }
    }

    setDrag({ x: 0, y: 0, active: false });
    axis.current = null;
  };

  const onViewerDown = (e) => {
    const p = e.touches ? e.touches[0] : e;
    start.current = { x: p.clientX, y: p.clientY };
    axis.current = "y";
    setDrag({ x: 0, y: 0, active: true });
  };

  const onViewerMove = (e) => {
    if (!drag.active) return;
    const p = e.touches ? e.touches[0] : e;
    const dy = p.clientY - start.current.y;
    setDrag({ x: 0, y: dy, active: true });
  };

  const onViewerUp = () => {
    const { y } = drag;
    const THRESH_Y = 70;
    if (Math.abs(y) > THRESH_Y && savedItems.length > 1) {
      if (y < 0) setViewerIndex((i) => (i + 1) % savedItems.length);
      if (y > 0) setViewerIndex((i) => (i - 1 + savedItems.length) % savedItems.length);
      registerTick();
    }
    setDrag({ x: 0, y: 0, active: false });
    axis.current = null;
  };

  const savedItems = ITEMS.filter((it) => saved.has(it.id));

  return (
    <div
      style={{
        minHeight: "680px",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: PALETTE.paper,
        fontFamily:
          "'Zen Maru Gothic', 'Hiragino Maru Gothic ProN', 'Hiragino Sans', sans-serif",
        padding: "24px 0",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Zen+Maru+Gothic:wght@400;500&family=Shippori+Mincho:wght@500&display=swap');
        @keyframes iyashiPulse {
          0% { filter: brightness(1) saturate(1); }
          50% { filter: brightness(1.08) saturate(1.15); }
          100% { filter: brightness(1) saturate(1); }
        }
        @keyframes iyashiBreathe {
          0% { transform: scale(1); }
          50% { transform: scale(1.08); }
          100% { transform: scale(1); }
        }
        @keyframes iyashiSway {
          0% { transform: rotate(-6deg); }
          50% { transform: rotate(6deg); }
          100% { transform: rotate(-6deg); }
        }
        @keyframes iyashiSpin {
          0% { transform: rotate(0deg) scale(1); }
          50% { transform: rotate(180deg) scale(1.1); }
          100% { transform: rotate(360deg) scale(1); }
        }
      `}</style>

      <div
        style={{
          width: 360,
          height: 720,
          borderRadius: 36,
          background: "#111",
          padding: 10,
          boxShadow: "0 20px 60px rgba(46,51,42,0.25)",
          position: "relative",
        }}
      >
        <div
          style={{
            width: "100%",
            height: "100%",
            borderRadius: 28,
            overflow: "hidden",
            position: "relative",
            background: "#000",
          }}
        >
          {view === "feed" && current && (
            <div
              onMouseDown={onDown}
              onMouseMove={onMove}
              onMouseUp={onUp}
              onMouseLeave={() => drag.active && onUp()}
              onTouchStart={onDown}
              onTouchMove={onMove}
              onTouchEnd={onUp}
              style={{
                width: "100%",
                height: "100%",
                position: "relative",
                touchAction: "none",
                cursor: drag.active ? "grabbing" : "grab",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  top: 16,
                  left: "50%",
                  transform: "translateX(-50%)",
                  color: "#fff",
                  fontSize: 13,
                  letterSpacing: 3,
                  opacity: 0.55,
                  fontFamily: "'Shippori Mincho', serif",
                  zIndex: 2,
                }}
              >
                Hitaru
              </div>

              {next && (
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    background: TAG_GRADIENTS[next.tag],
                    opacity: 0.6,
                  }}
                />
              )}

              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  transform: `translate(${drag.x}px, ${drag.y}px) rotate(${drag.x / 40}deg)`,
                  transition: drag.active ? "none" : "transform 320ms cubic-bezier(.2,.8,.2,1)",
                }}
              >
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    background: TAG_GRADIENTS[current.tag],
                    animation: current.kind === "video" ? "iyashiPulse 6s ease-in-out infinite" : "none",
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    background:
                      "linear-gradient(180deg, rgba(0,0,0,0.15) 0%, rgba(0,0,0,0) 30%, rgba(0,0,0,0) 60%, rgba(0,0,0,0.35) 100%)",
                  }}
                />
                {current.kind === "video" && (
                  <div
                    onMouseDown={(e) => e.stopPropagation()}
                    onClick={(e) => {
                      e.stopPropagation();
                      setVideoAudioOn((s) => {
                        const next = new Set(s);
                        next.has(current.id) ? next.delete(current.id) : next.add(current.id);
                        return next;
                      });
                    }}
                    style={{
                      position: "absolute",
                      top: "50%",
                      left: "50%",
                      transform: "translate(-50%,-50%)",
                      width: 56,
                      height: 56,
                      borderRadius: "50%",
                      background: "rgba(255,255,255,0.25)",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      backdropFilter: "blur(2px)",
                      cursor: "pointer",
                    }}
                  >
                    <Play size={22} color="#fff" fill="#fff" />
                  </div>
                )}

                {current.kind === "video" && (
                  <div
                    onMouseDown={(e) => e.stopPropagation()}
                    onClick={(e) => {
                      e.stopPropagation();
                      setVideoAudioOn((s) => {
                        const next = new Set(s);
                        next.has(current.id) ? next.delete(current.id) : next.add(current.id);
                        return next;
                      });
                    }}
                    style={{
                      position: "absolute",
                      top: 48,
                      left: 18,
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      background: "rgba(0,0,0,0.4)",
                      color: "#fff",
                      fontSize: 11,
                      padding: "6px 10px",
                      borderRadius: 16,
                      cursor: "pointer",
                    }}
                  >
                    {videoAudioOn.has(current.id) ? (
                      <>
                        <Volume2 size={13} />
                        動画の音声を再生中
                      </>
                    ) : (
                      <>
                        <Music size={13} />
                        動画の音声を聞く
                      </>
                    )}
                  </div>
                )}

                <div
                  style={{
                    position: "absolute",
                    left: 18,
                    bottom: 70,
                    color: "#fff",
                    fontSize: 13,
                    letterSpacing: 1,
                    opacity: 0.85,
                    fontFamily: "'Shippori Mincho', serif",
                  }}
                >
                  {current.tag}
                </div>

                <div
                  style={{
                    position: "absolute",
                    right: 14,
                    top: 16,
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    gap: 4,
                  }}
                >
                  <div
                    onMouseDown={(e) => e.stopPropagation()}
                    onClick={(e) => {
                      e.stopPropagation();
                      setSaved((s) => {
                        const next = new Set(s);
                        if (next.has(current.id)) {
                          next.delete(current.id);
                        } else {
                          next.add(current.id);
                          showFlash("保存しました");
                        }
                        return next;
                      });
                    }}
                    style={{
                      width: 44,
                      height: 44,
                      borderRadius: "50%",
                      background: saved.has(current.id)
                        ? PALETTE.dusk
                        : "rgba(255,255,255,0.18)",
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }}
                  >
                    <Bookmark
                      size={19}
                      color="#fff"
                      fill={saved.has(current.id) ? "#fff" : "none"}
                    />
                  </div>
                </div>
              </div>

              <div
                style={{
                  position: "absolute",
                  top: "50%",
                  right: 6,
                  transform: "translateY(-50%)",
                  display: "flex",
                  flexDirection: "column",
                  gap: 6,
                }}
              >
                {visible.slice(Math.max(0, safeIndex - 2), safeIndex + 3).map((it) => (
                  <div
                    key={it.id}
                    style={{
                      width: it.id === current.id ? 6 : 4,
                      height: it.id === current.id ? 6 : 4,
                      borderRadius: "50%",
                      background:
                        it.id === current.id ? "#fff" : "rgba(255,255,255,0.4)",
                    }}
                  />
                ))}
              </div>

              {flash && (
                <div
                  style={{
                    position: "absolute",
                    top: 26,
                    left: "50%",
                    transform: "translateX(-50%)",
                    background: "rgba(0,0,0,0.55)",
                    color: "#fff",
                    fontSize: 12,
                    padding: "6px 14px",
                    borderRadius: 20,
                  }}
                >
                  {flash}
                </div>
              )}
            </div>
          )}

          {view === "feed" && !current && (
            <div
              style={{
                width: "100%",
                height: "100%",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: PALETTE.mist,
                fontSize: 13,
                background: PALETTE.ink,
                textAlign: "center",
                padding: "0 40px",
              }}
            >
              今日はここまで。またゆっくり戻ってきてね。
            </div>
          )}

          {view === "mypage" && (
            <div
              style={{
                width: "100%",
                height: "100%",
                background: PALETTE.paper,
                padding: "22px 16px",
                overflowY: "auto",
              }}
            >
              <div
                style={{
                  fontFamily: "'Shippori Mincho', serif",
                  fontSize: 18,
                  color: PALETTE.ink,
                  marginBottom: 14,
                }}
              >
                ひたった記憶
              </div>
              {savedItems.length === 0 ? (
                <div style={{ fontSize: 13, color: PALETTE.moss, marginTop: 40, textAlign: "center" }}>
                  まだ何も保存されていません
                </div>
              ) : (
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1fr 1fr",
                    gap: 6,
                  }}
                >
                  {savedItems.map((it) => (
                    <div
                      key={it.id}
                      onClick={() => setViewerIndex(savedItems.findIndex((s) => s.id === it.id))}
                      style={{
                        aspectRatio: "1/1",
                        borderRadius: 8,
                        overflow: "hidden",
                        background: TAG_GRADIENTS[it.tag],
                        position: "relative",
                        cursor: "pointer",
                      }}
                    >
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setSaved((s) => {
                            const next = new Set(s);
                            next.delete(it.id);
                            return next;
                          });
                        }}
                        aria-label="保存から削除"
                        style={{
                          position: "absolute",
                          top: 4,
                          right: 4,
                          width: 22,
                          height: 22,
                          borderRadius: "50%",
                          border: "none",
                          background: "rgba(0,0,0,0.4)",
                          color: "#fff",
                          fontSize: 13,
                          lineHeight: 1,
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          cursor: "pointer",
                        }}
                      >
                        ×
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {viewerIndex !== null && savedItems[viewerIndex] && (() => {
            const item = savedItems[viewerIndex];
            const nextItem = savedItems.length > 1 ? savedItems[(viewerIndex + 1) % savedItems.length] : null;
            return (
              <div
                onMouseDown={onViewerDown}
                onMouseMove={onViewerMove}
                onMouseUp={onViewerUp}
                onMouseLeave={() => drag.active && onViewerUp()}
                onTouchStart={onViewerDown}
                onTouchMove={onViewerMove}
                onTouchEnd={onViewerUp}
                style={{
                  position: "absolute",
                  inset: 0,
                  zIndex: 5,
                  overflow: "hidden",
                  touchAction: "none",
                  cursor: drag.active ? "grabbing" : "grab",
                }}
              >
                {nextItem && (
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      background: TAG_GRADIENTS[nextItem.tag],
                      opacity: 0.6,
                    }}
                  />
                )}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    background: TAG_GRADIENTS[item.tag],
                    transform: `translateY(${drag.y}px)`,
                    transition: drag.active ? "none" : "transform 320ms cubic-bezier(.2,.8,.2,1)",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      background:
                        "linear-gradient(180deg, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0) 25%, rgba(0,0,0,0) 65%, rgba(0,0,0,0.4) 100%)",
                    }}
                  />
                  <div
                    style={{
                      position: "absolute",
                      left: 18,
                      bottom: 70,
                      color: "#fff",
                      fontSize: 13,
                      letterSpacing: 1,
                      opacity: 0.9,
                      fontFamily: "'Shippori Mincho', serif",
                    }}
                  >
                    {item.tag}
                  </div>
                  <button
                    onMouseDown={(e) => e.stopPropagation()}
                    onClick={(e) => {
                      e.stopPropagation();
                      setViewerIndex(null);
                    }}
                    style={{
                      position: "absolute",
                      left: 14,
                      bottom: 24,
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      border: "none",
                      background: "rgba(0,0,0,0.4)",
                      color: "#fff",
                      fontSize: 12,
                      padding: "8px 14px",
                      borderRadius: 20,
                      cursor: "pointer",
                    }}
                  >
                    ← トップに戻る
                  </button>
                  <button
                    onMouseDown={(e) => e.stopPropagation()}
                    onClick={(e) => {
                      e.stopPropagation();
                      setSaved((s) => {
                        const next = new Set(s);
                        next.delete(item.id);
                        return next;
                      });
                      setViewerIndex((i) =>
                        savedItems.length <= 1 ? null : i % (savedItems.length - 1)
                      );
                    }}
                    style={{
                      position: "absolute",
                      right: 14,
                      top: 16,
                      width: 44,
                      height: 44,
                      borderRadius: "50%",
                      border: "none",
                      background: "rgba(255,255,255,0.18)",
                      color: "#fff",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      cursor: "pointer",
                    }}
                    aria-label="保存から削除"
                  >
                    <Bookmark size={19} color="#fff" fill="#fff" />
                  </button>
                </div>
              </div>
            );
          })()}

          <div
            style={{
              position: "absolute",
              right: 10,
              bottom: 58,
              zIndex: 6,
              pointerEvents: "none",
            }}
          >
            <img
              src={
                sessionStage <= 1
                  ? HITARU_SAD
                  : sessionStage <= 3
                  ? HITARU_CALM
                  : HITARU_HAPPY
              }
              alt=""
              style={{
                width: sessionStage >= 4 ? 68 : sessionStage >= 2 ? 58 : 48,
                height: "auto",
                display: "block",
                filter:
                  sessionStage >= 2
                    ? `drop-shadow(0 0 ${6 + sessionStage * 3}px rgba(133,119,160,0.55))`
                    : "none",
                animation:
                  sessionStage >= 5
                    ? "iyashiSpin 4s ease-in-out infinite"
                    : sessionStage === 4
                    ? "iyashiSway 3s ease-in-out infinite"
                    : sessionStage === 3
                    ? "iyashiBreathe 3.5s ease-in-out infinite"
                    : "none",
                transition: "width 400ms ease, filter 400ms ease",
              }}
            />
          </div>

          <button
            onClick={() => setSessionTicks(0)}
            style={{
              position: "absolute",
              left: 10,
              bottom: 16,
              zIndex: 6,
              fontSize: 10,
              padding: "4px 8px",
              borderRadius: 10,
              border: "none",
              background: "rgba(0,0,0,0.35)",
              color: "#fff",
              opacity: 0.6,
              cursor: "pointer",
            }}
          >
            デモ: アプリを開き直す
          </button>

          <div
            style={{
              position: "absolute",
              bottom: 0,
              left: 0,
              right: 0,
              height: 54,
              background: "rgba(255,255,255,0.9)",
              backdropFilter: "blur(6px)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-around",
              borderTop: `0.5px solid ${PALETTE.mist}`,
            }}
          >
            <button
              onClick={() => setView("feed")}
              style={{
                background: "none",
                border: "none",
                fontSize: 12,
                color: view === "feed" ? PALETTE.moss : PALETTE.ink,
                fontWeight: view === "feed" ? 500 : 400,
                fontFamily: "inherit",
                cursor: "pointer",
              }}
            >
              ホーム
            </button>
            <button
              onClick={() => setView("mypage")}
              style={{
                background: "none",
                border: "none",
                fontSize: 12,
                color: view === "mypage" ? PALETTE.moss : PALETTE.ink,
                fontWeight: view === "mypage" ? 500 : 400,
                fontFamily: "inherit",
                cursor: "pointer",
              }}
            >
              保存({savedItems.length})
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
